<?php
declare(strict_types=1);
namespace HardnessMcp\Tools\Finance\Infrastructure;
use HardnessMcp\Tools\Finance\Domain\FinanceSummaryRepositoryInterface;use PDO;
final class PdoFinanceSummaryRepository implements FinanceSummaryRepositoryInterface {
    private PDO $pdo;public function __construct(PDO $pdo){$this->pdo=$pdo;}
    public function summary(string $kind,int $companyId,string $from,string $to,string $status,?int $partnerId,?int $carrierId,string $dateBasis='due_date',?string $cursor=null):array{[$source,$where,$params]=$this->parts($kind,$companyId,$from,$to,$status,$partnerId,$carrierId,$dateBasis);$s=$this->pdo->prepare('SELECT COALESCE(SUM(total_amount),0) total_amount,COALESCE(SUM(settled_amount),0) settled_amount,COALESCE(SUM(open_amount),0) open_amount,COALESCE(SUM(overdue_amount),0) overdue_amount,COUNT(*) title_count FROM '.$source.' '.$where);$s->execute($params);return (array)$s->fetch();}
    public function grouped(string $kind,int $companyId,string $from,string $to,string $status,?int $partnerId,?int $carrierId,string $groupBy,int $limit,string $dateBasis='due_date'):array{$basisColumn=$dateBasis==='settlement_date'?'settlement_date':'due_date';[$source,$where,$params]=$this->parts($kind,$companyId,$from,$to,$status,$partnerId,$carrierId,$dateBasis);$totals='COALESCE(SUM(total_amount),0) total_amount,COALESCE(SUM(settled_amount),0) settled_amount,COALESCE(SUM(open_amount),0) open_amount,COALESCE(SUM(overdue_amount),0) overdue_amount,COUNT(*) title_count';$select=$totals;$group='';$order='';if($groupBy==='day'){$select=$basisColumn.' date,'.$totals;$group=' GROUP BY '.$basisColumn;$order=' ORDER BY date ASC';}if($groupBy==='month'){$select="DATE_FORMAT(".$basisColumn.", '%Y-%m-01') month,".$totals;$group=" GROUP BY DATE_FORMAT(".$basisColumn.", '%Y-%m-01')";$order=' ORDER BY month ASC';}if($groupBy==='partner'){$select='partner_id,partner_name,'.$totals;$group=' GROUP BY partner_id,partner_name';$order=' ORDER BY open_amount DESC,partner_id ASC';}if($groupBy==='carrier'){$select='carrier_id,carrier_name,'.$totals;$group=' GROUP BY carrier_id,carrier_name';$order=' ORDER BY open_amount DESC,carrier_id ASC';}if($groupBy==='origin'){$select='origin,'.$totals;$group=' GROUP BY origin';$order=' ORDER BY open_amount DESC,origin ASC';}if($groupBy==='status'){$select='title_status status,'.$totals;$group=' GROUP BY title_status';$order=' ORDER BY status ASC';}$s=$this->pdo->prepare('SELECT '.$select.' FROM '.$source.' '.$where.$group.$order.' LIMIT :limit');foreach($params as $name=>$value)$s->bindValue(':'.$name,$value,is_int($value)?PDO::PARAM_INT:PDO::PARAM_STR);$s->bindValue(':limit',min($limit,51),PDO::PARAM_INT);$s->execute();$rows=$s->fetchAll();return is_array($rows)?$rows:[];}
    public function titles(string $kind,int $companyId,string $from,string $to,string $status,?int $partnerId,?int $carrierId,int $limit,string $dateBasis='due_date',?array $cursor=null):array{[$source,$where,$params]=$this->parts($kind,$companyId,$from,$to,$status,$partnerId,$carrierId,$dateBasis);if($cursor!==null){$where.=' AND (due_date>:cursor_due_date_after OR (due_date=:cursor_due_date_same AND title_id>:cursor_title_id))';$params['cursor_due_date_after']=$cursor['due_date'];$params['cursor_due_date_same']=$cursor['due_date'];$params['cursor_title_id']=$cursor['title_id'];}$s=$this->pdo->prepare('SELECT title_id,partner_id,partner_name,carrier_id,carrier_name,origin,invoice_number,invoice_issued_date,document_number,due_date,settlement_date,total_amount,open_amount,title_status FROM '.$source.' '.$where.' ORDER BY due_date ASC,title_id ASC LIMIT :limit');foreach($params as $name=>$value)$s->bindValue(':' . $name,$value,is_int($value)?PDO::PARAM_INT:PDO::PARAM_STR);$s->bindValue(':limit',min($limit,51),PDO::PARAM_INT);$s->execute();$rows=$s->fetchAll();return is_array($rows)?$rows:[];}
    /** @return array{0:string,1:string,2:array<string,int|string>} */ private function parts(string $kind,int $companyId,string $from,string $to,string $status,?int $partnerId,?int $carrierId,string $dateBasis):array{if($kind==='receivable'){$source="(SELECT t.T002_Id title_id,t.T002_Data_Vencimento due_date,t.T002_Data_Recebimento settlement_date,t.T002_Numero_Documento document_number,COALESCE(t.T002_Numero_Nota_Fiscal,n.T007_Numero_Nota_Fiscal) invoice_number,n.T007_Data_Emissao invoice_issued_date,t.T002_D024_Id partner_id,COALESCE(NULLIF(p.D024_Nome_Fantasia,''),p.D024_Nome_Empresa,t.T002_Nome_Cliente) partner_name,t.T002_D027_Id carrier_id,c.D027_Portador carrier_name,CASE WHEN t.T002_T007_Id IS NOT NULL AND t.T002_T117_Id IS NOT NULL THEN 'nota_saida_e_boleto' WHEN t.T002_T007_Id IS NOT NULL THEN 'nota_saida' WHEN t.T002_T117_Id IS NOT NULL THEN 'boleto' ELSE 'manual' END origin,t.T002_Valor_Total total_amount,CASE WHEN COALESCE(t.T002_Valor_Saldo,t.T002_Valor_Total-COALESCE(t.T002_Valor_Recebido,0))<=0 THEN t.T002_Valor_Total ELSE 0 END settled_amount,GREATEST(COALESCE(t.T002_Valor_Saldo,t.T002_Valor_Total-COALESCE(t.T002_Valor_Recebido,0)),0) open_amount,CASE WHEN GREATEST(COALESCE(t.T002_Valor_Saldo,t.T002_Valor_Total-COALESCE(t.T002_Valor_Recebido,0)),0)>0 AND t.T002_Data_Vencimento<CURDATE() THEN GREATEST(COALESCE(t.T002_Valor_Saldo,t.T002_Valor_Total-COALESCE(t.T002_Valor_Recebido,0)),0) ELSE 0 END overdue_amount,CASE WHEN GREATEST(COALESCE(t.T002_Valor_Saldo,t.T002_Valor_Total-COALESCE(t.T002_Valor_Recebido,0)),0)<=0 THEN 'settled' WHEN t.T002_Data_Vencimento<CURDATE() THEN 'overdue' ELSE 'open' END title_status FROM T002 t LEFT JOIN D024 p ON p.D024_Id=t.T002_D024_Id LEFT JOIN D027 c ON c.D027_Id=t.T002_D027_Id LEFT JOIN T007 n ON n.T007_Id=t.T002_T007_Id WHERE t.T002_C004_Id=:company_id AND t.T002_Flag_Cancelada='N' AND COALESCE(t.T002_T002_Id_Agrupado,0)=0) finance";}else{$source="(SELECT t.T015_Id title_id,t.T015_Data_Vencimento due_date,t.T015_Data_Pagamento settlement_date,t.T015_Numero_Documento document_number,COALESCE(t.T015_Numero_Nota_Fiscal,n.T013_Numero_Nota_Fiscal) invoice_number,n.T013_Data_Emissao invoice_issued_date,t.T015_D024_Id partner_id,COALESCE(NULLIF(p.D024_Nome_Fantasia,''),p.D024_Nome_Empresa,t.T015_Nome_Cliente) partner_name,t.T015_D031_Id carrier_id,c.D031_Portador carrier_name,CASE WHEN t.T015_T013_Id IS NOT NULL AND t.T015_T084_Id IS NOT NULL THEN 'nota_entrada_e_cte' WHEN t.T015_T013_Id IS NOT NULL THEN 'nota_entrada' WHEN t.T015_T084_Id IS NOT NULL THEN 'cte' ELSE 'manual' END origin,t.T015_Valor_Total total_amount,CASE WHEN COALESCE(t.T015_Valor_Saldo,t.T015_Valor_Total-COALESCE(t.T015_Valor_Pago,0))<=0 THEN t.T015_Valor_Total ELSE 0 END settled_amount,GREATEST(COALESCE(t.T015_Valor_Saldo,t.T015_Valor_Total-COALESCE(t.T015_Valor_Pago,0)),0) open_amount,CASE WHEN GREATEST(COALESCE(t.T015_Valor_Saldo,t.T015_Valor_Total-COALESCE(t.T015_Valor_Pago,0)),0)>0 AND t.T015_Data_Vencimento<CURDATE() THEN GREATEST(COALESCE(t.T015_Valor_Saldo,t.T015_Valor_Total-COALESCE(t.T015_Valor_Pago,0)),0) ELSE 0 END overdue_amount,CASE WHEN GREATEST(COALESCE(t.T015_Valor_Saldo,t.T015_Valor_Total-COALESCE(t.T015_Valor_Pago,0)),0)<=0 THEN 'settled' WHEN t.T015_Data_Vencimento<CURDATE() THEN 'overdue' ELSE 'open' END title_status FROM T015 t LEFT JOIN D024 p ON p.D024_Id=t.T015_D024_Id LEFT JOIN D031 c ON c.D031_Id=t.T015_D031_Id LEFT JOIN T013 n ON n.T013_Id=t.T015_T013_Id WHERE t.T015_C004_Id=:company_id AND t.T015_Flag_Cancelada='N') finance";}$dateColumn=$dateBasis==='settlement_date'?'settlement_date':'due_date';$where='WHERE '.$dateColumn.'>=:date_from AND '.$dateColumn.'<=:date_to';$params=['company_id'=>$companyId,'date_from'=>$from,'date_to'=>$to];if($status!=='all'){$where.=' AND title_status=:status';$params['status']=$status;}if($partnerId!==null){$where.=' AND partner_id=:partner_id';$params['partner_id']=$partnerId;}if($carrierId!==null){$where.=' AND carrier_id=:carrier_id';$params['carrier_id']=$carrierId;}return [$source,$where,$params];}
}
